using System.Security.Cryptography;
using System.Text.Json;
using NoIntrovert.Ctr.Keys;

namespace NoIntrovert.Ctr.Tests;

/// <summary>
/// Access to the synthetic fixtures generated by reference/python/gen_fixtures.py.
/// Every expected value comes from the Python reference implementation, so these tests
/// check that the C# library is byte-for-byte identical to it. The keys are fake.
/// </summary>
internal static class Fixtures
{
    public static string Dir { get; } = Path.Combine(AppContext.BaseDirectory, "fixtures");

    public static string File(string relative) => Path.Combine(Dir, relative.Replace('/', Path.DirectorySeparatorChar));

    private static readonly Lazy<JsonElement> ExpectedJson = new(() =>
        JsonDocument.Parse(System.IO.File.ReadAllText(File("expected.json"))).RootElement);

    public static JsonElement Expected(string name) => ExpectedJson.Value.GetProperty(name);

    public static string ExpectedSha256(string name) => Expected(name).GetProperty("sha256").GetString()!;

    public static string Fact(string name) => ExpectedJson.Value.GetProperty("_facts").GetProperty(name).ToString();

    /// <summary>Key store loaded with the fake keys (unknown boot9 hash allowed).</summary>
    public static CtrKeyStore Keys(bool seeds = true, bool certs = true)
    {
        var ks = new CtrKeyStore();
        ks.LoadBoot9(System.IO.File.ReadAllBytes(File("keys/boot9_fake.bin")), requireKnownHash: false);
        ks.LoadAesKeysFile(File("keys/aes_keys_fake.txt"));
        if (seeds) ks.LoadSeedDbFile(File("keys/seeddb_fake.bin"));
        if (certs) ks.SetCertificateChain(System.IO.File.ReadAllBytes(File("keys/certs_fake.bin")));
        return ks;
    }

    public static string Sha256OfFile(string path)
    {
        using var fs = System.IO.File.OpenRead(path);
        return Convert.ToHexString(SHA256.HashData(fs)).ToLowerInvariant();
    }
}

/// <summary>A temporary directory deleted at the end of a test.</summary>
internal sealed class TempDir : IDisposable
{
    public TempDir()
    {
        Path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "nointrovert-tests-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(Path);
    }

    public string Path { get; }
    public string File(string name) => System.IO.Path.Combine(Path, name);

    public void Dispose()
    {
        try { Directory.Delete(Path, recursive: true); } catch (IOException) { }
    }
}
